const spanMethod = ({ row, column, rowIndex, columnIndex }) => {
// 合并第一列（例如 token 列）
  if (columnIndex === 0) {
    if (rowIndex === 0 || row.token !== QwenWeirdOutputData[rowIndex - 1].token) {
      let rowspan = 1;
      for (let i = rowIndex + 1; i < QwenWeirdOutputData.length; i++) {
        if (QwenWeirdOutputData[i].token === row.token) {
          rowspan++;
        } else {
          break;
        }
      }
      return { rowspan, colspan: 1 };
      } else {
        return { rowspan: 0, colspan: 0 };
    }
  }

  // 合并第二列（例如 content 列）
  else if (columnIndex === 1) {
    if (rowIndex === 0 || row.model !== QwenWeirdOutputData[rowIndex - 1].model) {
    let rowspan = 1;
    for (let i = rowIndex + 1; i < QwenWeirdOutputData.length; i++) {
      if (QwenWeirdOutputData[i].model === row.model) {
          rowspan++;
        } else {
          break;
        }
      }
      return { rowspan, colspan: 1 };
    } else {
      return { rowspan: 0, colspan: 0 };
    }
  }

  // 其它列不做合并
  return { rowspan: 1, colspan: 1 };
};


